import { readFileSync } from "node:fs";

import { API_URL } from "../../playwright.config";
import { expect, sample, test, uniqueName } from "../../fixtures";

test("audit events are listed oldest first with actor and action", { tag: "@AUD-01" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");
  const created = await member.post("/api/vendors", {
    data: {
      name: uniqueName("Audit Vendor"),
      category: "services",
      contact_email: "billing@audit-vendor.com",
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendorId = ((await created.json()) as { id: string }).id;

  const upload = await member.post(`/api/vendors/${vendorId}/documents`, {
    multipart: {
      kind: "w9",
      file: {
        name: "w9.txt",
        mimeType: "text/plain",
        buffer: readFileSync(sample("w9.txt")),
      },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);

  // Act: extraction runs in the background, so wait for its audit event.
  type AuditEvent = { action: string; actor: { email: string }; at: string };
  let items: AuditEvent[] = [];
  await expect
    .poll(
      async () => {
        const response = await member.get(`/api/vendors/${vendorId}/audit`);
        expect(response.status(), await response.text()).toBe(200);
        items = ((await response.json()) as { items: AuditEvent[] }).items;
        return items.map((e) => e.action);
      },
      { timeout: 30_000 },
    )
    .toEqual(["vendor.created", "document.uploaded", "document.extracted"]);

  // Assert
  expect(API_URL).toBeTruthy();
  for (const event of items) {
    expect(event.actor.email).toBe("member@northwind.test");
    expect(event.at).toBeTruthy();
    expect(Number.isNaN(Date.parse(event.at))).toBe(false);
  }
});
